const list=document.getElementById('list');
const input=document.getElementById('newItem');
const msg=document.getElementById('msg');
const empty=document.getElementById('empty');
const count=document.getElementById('count');
const clearBtn=document.getElementById('clearBtn');
let items=[];let revs={};
async function load(){
try{const r=await tessera.call('data.read',{});items=r.data.items||[];revs=(r.revisions&&r.revisions.items)||{};render();}
catch(e){msg.textContent='Could not load the list. Please try again.';}
}
function render(){
list.textContent='';
for(const it of items){
const li=document.createElement('li');
if(it.done)li.className='done';
const lab=document.createElement('label');
const cb=document.createElement('input');cb.type='checkbox';cb.checked=!!it.done;
const sp=document.createElement('span');sp.textContent=it.name;
lab.appendChild(cb);lab.appendChild(sp);
cb.addEventListener('change',()=>toggle(it.id,cb.checked,cb));
const del=document.createElement('button');del.type='button';del.className='del';del.textContent='Remove';
