}
const doneN=items.filter(i=>i.done).length;
empty.hidden=items.length>0;
clearBtn.hidden=doneN===0;
count.textContent=items.length?(doneN+' of '+items.length+' ticked'):'';
}
async function toggle(id,val,cb){
try{await tessera.call('data.patch',{operations:[{op:'replace',collection:'items',id:id,revisionCount:revs[id],fields:{done:val}}]});msg.textContent='';await load();}
catch(e){cb.checked=!val;msg.textContent='Could not update that item. Please try again.';}
}
async function remove(id,name){
try{await tessera.call('data.patch',{operations:[{op:'remove',collection:'items',id:id,revisionCount:revs[id]}]});msg.textContent=name+' removed.';await load();input.focus();}
catch(e){msg.textContent='Could not remove '+name+'. Please try again.';}
}
async function add(){
const name=input.value.trim();
if(!name){msg.textContent='Type an item name first.';input.focus();return;}
try{await tessera.call('data.patch',{operations:[{op:'add',collection:'items',record:{name:name,done:false}}]});input.value='';msg.textContent=name+' added.';await load();input.focus();}
catch(e){msg.textContent='Could not add the item. Your text is still here; please try again.';}
}
async function clearDone(){
const ops=items.filter(i=>i.done).map(i=>({op:'remove',collection:'items',id:i.id,revisionCount:revs[i.id]}));
if(!ops.length)return;
try{await tessera.call('data.patch',{operations:ops});msg.textContent=ops.length+' ticked item(s) removed.';await load();input.focus();}
catch(e){msg.textContent='Could not remove the ticked items. Please try again.';}
}
document.getElementById('addBtn').addEventListener('click',add);
input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();add();}});
clearBtn.addEventListener('click',clearDone);
load();
